    regs_ok (ENV vals) srI0 R -> know_ok RSEGS (ENV vals) M knI0 ->
    realizes RSEGS (mkCfg (mkst R (Z_to_bv 64 0x10073c) M (seg_rom RSEGS)) model)
               (t_exit (exit_code 2) (m_fs model)).
